function compute(inputs) {
  const Q = inputs.Q;
  const K = inputs.K;
  const V = inputs.V;
  const scale = inputs.scale;
  const dk = Q[0].length;
  const n = Q.length;
  const m = K.length;
  const sqrt_dk = Math.sqrt(dk);
  const scores = [];
  for (let i = 0; i < n; i++) {
    scores[i] = [];
    for (let j = 0; j < m; j++) {
      let dot = 0;
      for (let d = 0; d < dk; d++) {
        dot += Q[i][d] * K[j][d];
      }
      scores[i][j] = scale ? dot / sqrt_dk : dot;
    }
  }
  const weights = [];
  for (let i = 0; i < n; i++) {
    const row = scores[i];
    const maxScore = Math.max(...row);
    const exps = row.map(s => Math.exp(s - maxScore));
    const sumExps = exps.reduce((a, b) => a + b, 0);
    weights[i] = exps.map(e => e / sumExps);
  }
  const output = [];
  for (let i = 0; i < n; i++) {
    output[i] = [];
    for (let d = 0; d < V[0].length; d++) {
      let sum = 0;
      for (let j = 0; j < m; j++) {
        sum += weights[i][j] * V[j][d];
      }
      output[i][d] = sum;
    }
  }
  const table = {
    columns: ["Query i", "Key j", "Score s_ij", "Weight a_ij", "Contribution a_ij * V_j"],
    rows: []
  };
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      const contrib = weights[i][j] * V[j][0];
      table.rows.push([i+1, j+1, scores[i][j].toFixed(3), weights[i][j].toFixed(3), contrib.toFixed(3)]);
    }
  }
  const rowSums = weights.map(row => row.reduce((a, b) => a + b, 0));
  const maxWeight = Math.max(...weights.flat());
  const insight = `Max weight = ${maxWeight.toFixed(3)}. ` + (maxWeight > 0.9 ? "One key dominates." : "Weights are spread out.");
  return {
    scores: scores,
    weights: weights,
    output: output,
    table: table,
    rowSums: rowSums,
    insight: insight
  };
}
